// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    FeeToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new FeeToken();
    }

    function testFuzz_property(uint256 premium, uint256 fee, uint256 duration, uint256 t) public {
        // admissible domain: fee < 30, duration < 10000 days, premium small enough that
        // premium*fee never overflows and the accrued fee is strictly positive
        premium = bound(premium, 1000, 10 ** 15);
        fee = bound(fee, 1, 29);
        duration = bound(duration, 1, 10_000 days - 1);
        t = bound(t, 1, 10 ** 12);
        vm.warp(t);

        // fee is only accrued via fillOrder; enable it (test contract is owner)
        c.setFee(fee);

        // order maker must sign or present a valid ERC-1271 signature:
        // deploy a maker contract whose isValidSignature returns the magic value
        Maker maker = new Maker();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: premium,
            duration: duration,
            expiration: t + duration + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(0);
        uint256[] memory noFloorIds = new uint256[](0);

        vm.prank(address(0xbeef));
        c.fillOrder(order, sig, noFloorIds);

        // fees were accrued on the base asset: premium*fee/1000 > 0 is guaranteed
        // by the bounds (premium >= 1000, fee >= 1)
        c.withdrawFees(address(token), address(this));

        // RULE: withdrawing the fees always clears the recorded unclaimed fees
        assertTrue(c.unclaimedFees(address(token)) == 0, "unclaimedFees not cleared by withdrawFees");
    }
}

// ERC-20 stand-in for the base asset: accepts all transfers, records them
contract FeeToken {
    event GotTransfer(address indexed from, address indexed to, uint256 amount, bool isTransferFrom);

    uint256 public lastAmount;

    function transfer(address to, uint256 amount) external returns (bool) {
        lastAmount = amount;
        emit GotTransfer(msg.sender, to, amount, false);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastAmount = amount;
        emit GotTransfer(from, to, amount, true);
        return true;
    }
}

// ERC-1271 signer used as the order maker so the signature check passes
contract Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}
